// Vercel Routing Middleware: answers `Accept: text/markdown` with the page's Markdown twin.
// Runs only on the sitemap pages in `config.matcher` (Mike, 2026-11-24: "do every page" for Peec's
// "Serve Markdown versions of pages"). Every other request, and every request that doesn't ask for
// Markdown, falls straight through to the normal HTML (returning nothing = continue).
// Why middleware: Vercel serves a static file before any vercel.json rewrite, so a header rewrite can
// never fire on /about etc. The twins themselves are generated by scripts/build-markdown.mjs.

// Keep in step with `config.matcher` (a literal Vercel reads at build time) and the sitemaps;
// middleware.test.ts fails if they drift.
export const MARKDOWN_TWINS: Record<string, string> = {
  "/": "/home.md",
  "/about": "/about.md",
  "/blog": "/blog.md",
  "/compare": "/compare.md",
  "/compare/best-anki-alternatives": "/compare/best-anki-alternatives.md",
  "/compare/best-apps-to-remember-what-you-read": "/compare/best-apps-to-remember-what-you-read.md",
  "/compare/best-obsidian-alternatives": "/compare/best-obsidian-alternatives.md",
  "/compare/best-pocket-alternatives": "/compare/best-pocket-alternatives.md",
  "/compare/best-quizlet-alternatives": "/compare/best-quizlet-alternatives.md",
  "/compare/best-readwise-alternatives": "/compare/best-readwise-alternatives.md",
  "/compare/best-spaced-repetition-apps": "/compare/best-spaced-repetition-apps.md",
  "/compare/reps-vs-readwise": "/compare/reps-vs-readwise.md",
  "/facts": "/facts.md",
  "/features/active-recall": "/features/active-recall.md",
  "/features/read-it-later": "/features/read-it-later.md",
  "/features/second-brain": "/features/second-brain.md",
  "/newsroom": "/newsroom.md",
  "/planet": "/planet.md",
};

export const config = {
  matcher: [
    "/",
    "/about",
    "/blog",
    "/compare",
    "/compare/best-anki-alternatives",
    "/compare/best-apps-to-remember-what-you-read",
    "/compare/best-obsidian-alternatives",
    "/compare/best-pocket-alternatives",
    "/compare/best-quizlet-alternatives",
    "/compare/best-readwise-alternatives",
    "/compare/best-spaced-repetition-apps",
    "/compare/reps-vs-readwise",
    "/facts",
    "/features/active-recall",
    "/features/read-it-later",
    "/features/second-brain",
    "/newsroom",
    "/planet",
  ],
};

// True when the Accept header lists text/markdown with a non-zero q (browsers never send it).
export function wantsMarkdown(accept: string | null): boolean {
  if (!accept) return false;
  return accept.split(",").some((entry) => {
    const [type, ...params] = entry.split(";").map((p) => p.trim().toLowerCase());
    if (type !== "text/markdown") return false;
    const q = params.find((p) => p.startsWith("q="));
    return q === undefined || Number(q.slice(2)) > 0;
  });
}

export async function handle(request: Request, fetchImpl: typeof fetch): Promise<Response | undefined> {
  if (request.method !== "GET" && request.method !== "HEAD") return undefined;
  if (!wantsMarkdown(request.headers.get("accept"))) return undefined;
  const url = new URL(request.url);
  const twin = MARKDOWN_TWINS[url.pathname];
  if (!twin) return undefined;
  try {
    // The .md path is outside the matcher, so this fetch is served as a plain static file
    // (with the Content-Type and rel=canonical headers vercel.json sets for *.md).
    const res = await fetchImpl(new URL(twin, url.origin).toString());
    if (!res.ok) {
      console.warn(`markdown twin ${twin} answered ${res.status}; serving HTML instead`);
      return undefined;
    }
    const headers = new Headers(res.headers);
    headers.set("Content-Type", "text/markdown; charset=utf-8");
    headers.set("Vary", "Accept");
    return new Response(request.method === "HEAD" ? null : res.body, { status: 200, headers });
  } catch (err) {
    console.warn(`markdown twin ${twin} failed; serving HTML instead`, err);
    return undefined;
  }
}

export default function middleware(request: Request): Promise<Response | undefined> {
  return handle(request, fetch);
}
